# Build the 30x30 patterned test and apply separator-only links between repeated tile colors.
N=30
g=[[0]*N for _ in range(N)]
pat=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
starts=[1,8,15,22,29]
# Each tile has a 5x5 frame (color 4) and uniform 3x3 core; preserve clipped fifth row/column.
for tr,r0 in enumerate(starts):
  for tc,c0 in enumerate(starts):
    for dr in range(5):
      for dc in range(5):
        r,c=r0+dr,c0+dc
        if r<N and c<N:
          g[r][c]=4 if dr in (0,4) or dc in (0,4) else (pat[tr][tc] if tr<4 and tc<4 else 4)
# For each complete tile-row, link matching core colors through inter-tile column gaps.
for tr in range(4):
  vals=pat[tr]
  for color in set(vals):
    ix=[tc for tc,v in enumerate(vals) if v==color]
    if len(ix)>1:
      for gapidx in range(min(ix),max(ix)):
        cstart=starts[gapidx]+5
        for rr in range(starts[tr]+1,starts[tr]+4):
          for c in (cstart,cstart+1):
            if r<N and c<N: g[rr][c]=color
# For each complete tile-column, link matching core colors through inter-tile row gaps.
for tc in range(4):
  vals=[pat[tr][tc] for tr in range(4)]
  for color in set(vals):
    ix=[tr for tr,v in enumerate(vals) if v==color]
    if len(ix)>1:
      for gapidx in range(min(ix),max(ix)):
        rstart=starts[gapidx]+5
        for cc in range(starts[tc]+1,starts[tc]+4):
          for r in (rstart,rstart+1):
            if r<N and cc<N: g[r][cc]=color
print(g)

